<div class="mb-8 flex flex-wrap items-end justify-between gap-4"><div><p class="text-[10px] font-bold uppercase tracking-[.2em] text-[#687158]">Your feedback</p><h1 class="mt-2 text-3xl font-medium">Reviews</h1><p class="mt-2 text-sm text-[#77796f]">Share your experience with the collection.</p></div><button class="rounded-xl bg-[#687158] px-4 py-3 text-xs font-semibold text-white" onclick="document.getElementById('review-modal').classList.replace('hidden','flex')">＋ Write a review</button></div><div class="space-y-4"><?php if(!$reviews): ?><div class="rounded-2xl border border-dashed border-[#d6d6cd] p-8 text-sm text-[#77796f]">You have not written any reviews yet.</div><?php endif; ?><?php foreach($reviews as $review): ?><article class="rounded-2xl border border-[#e5e5dd] bg-[#fbfbf7] p-5"><div class="flex flex-wrap items-start justify-between gap-3"><div><h2 class="font-medium"><?= e($review['product']) ?></h2><div class="mt-2 text-sm tracking-widest text-[#b28d43]"><?= str_repeat('★',(int)$review['rating']) ?><span class="text-[#ddd8cc]"><?= str_repeat('★',5-(int)$review['rating']) ?></span></div></div><span class="text-[10px] text-[#92948a]"><?= e($review['date']) ?></span></div><p class="mt-4 text-sm leading-6 text-[#77796f]">“<?= e($review['text']) ?>”</p><span class="mt-4 inline-block rounded-full bg-[#f0f1e9] px-3 py-1 text-[10px] text-[#687158]">Submitted</span></article><?php endforeach; ?></div><div id="review-modal" class="fixed inset-0 z-50 hidden items-center justify-center bg-[#252820]/40 p-5"><form id="review-form" class="w-full max-w-lg rounded-2xl bg-[#fbfbf7] p-6 shadow-2xl"><div class="mb-5 flex items-center justify-between"><div><p class="text-[10px] font-bold uppercase tracking-[.2em] text-[#687158]">Your feedback</p><h2 class="mt-2 text-xl font-medium">Write a review</h2></div><button type="button" onclick="document.getElementById('review-modal').classList.replace('flex','hidden')">×</button></div><div class="grid gap-4"><label class="grid gap-2 text-xs text-[#77796f]">Product name<input name="product" required class="rounded-xl border border-[#deded6] bg-white p-3"></label><label class="grid gap-2 text-xs text-[#77796f]">Rating<select name="rating" class="rounded-xl border border-[#deded6] bg-white p-3"><option value="5">5 — Excellent</option><option value="4">4 — Very good</option><option value="3">3 — Good</option><option value="2">2 — Fair</option><option value="1">1 — Poor</option></select></label><label class="grid gap-2 text-xs text-[#77796f]">Review<textarea name="text" rows="5" required class="rounded-xl border border-[#deded6] bg-white p-3"></textarea></label></div><button class="mt-6 w-full rounded-xl bg-[#687158] px-4 py-3 text-sm font-semibold text-white">Submit review</button></form></div><script>$('#review-form').on('submit',function(e){e.preventDefault();$.post('<?= e(($base?:'').'/customer/ajax/review-add') ?>',$(this).serialize()).done(function(r){customerToast(r.message||'Review submitted.');setTimeout(()=>location.reload(),500)}).fail(function(x){customerToast((x.responseJSON||{}).message||'Could not submit review.')})})</script>
